#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n, m; scanf("%d %d", &n, &m);
        vector<long long> v(n);
        for (auto &x : v) scanf("%lld", &x);
        vector<vector<long long>> a(n, vector<long long>(m));
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) scanf("%lld", &a[i][j]);
        long long best = m;                      // emptying one row always works
        multiset<long long, greater<long long>> ms;  // top-m values of rows >= k
        for (int k = n - 1; k >= 0; k--) {
            for (int j = 0; j < m; j++) {
                ms.insert(a[k][j]);
                if ((int)ms.size() > m) ms.erase(prev(ms.end()));
            }
            long long s = 0; int cnt = 0;
            for (long long x : ms) {
                if (s >= v[k]) break;
                s += x; cnt++;
            }
            if (s >= v[k]) best = min(best, (long long)cnt);
        }
        printf("%lld\n", best);
    }
}

#include <bits/stdc++.h>
