int main() {
    int t; cin >> t;
    while (t--) {
        int n, k; cin >> n >> k;
        vector<int> a(n);
        for (auto &x : a) cin >> x;
        set<int> distinct(a.begin(), a.end());
        int d = distinct.size();
        if (k == 1) cout << (d == 1 ? 1 : -1) << "\n";
