#include <bits/stdc++.h>
using namespace std;
int main() {
    long long n; cin >> n;
    long long px = 0, py = 0, ans = 1;          // the 0:0 start is a draw
    for (long long i = 0; i < n; i++) {
        long long a, b; cin >> a >> b;
        long long L = max(px, py), R = min(a, b);  // diagonal points reachable on this segment
        long long cnt = R - L + 1 - (px == py ? 1 : 0);  // previous checkpoint already counted
        if (cnt > 0) ans += cnt;
        px = a; py = b;
    }
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    string s; int m; cin >> s >> m;
    int n = s.size();
    vector<int> cnt(n + 2, 0);
    for (int i = 0; i < m; i++) { int a; cin >> a; cnt[a] ^= 1; }
    int par = 0;
    for (int p = 1; p <= n / 2; p++) {
        par ^= cnt[p];                 // parity of reversals whose segment covers pair p
        if (par) swap(s[p - 1], s[n - p]);
    }
    cout << s << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    string s; cin >> s;
    const long long MOD = 1000000007LL;
    long long ans = 0, b = 0;   // b = number of 'b' to the right of the current position
    for (int i = (int)s.size() - 1; i >= 0; i--) {
        if (s[i] == 'b') b = (b + 1) % MOD;
        else ans = (2 * ans + b) % MOD;
    }
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    long long lo = -2000000000LL, hi = 2000000000LL;   // feasible range for y
    for (int i = 0; i < n; i++) {
        string op, ans; long long x;
        cin >> op >> x >> ans;
        bool yes = (ans == "Y");
        if (op == ">") { if (yes) lo = max(lo, x + 1); else hi = min(hi, x); }
        else if (op == "<") { if (yes) hi = min(hi, x - 1); else lo = max(lo, x); }
        else if (op == ">=") { if (yes) lo = max(lo, x); else hi = min(hi, x - 1); }
        else { if (yes) hi = min(hi, x); else lo = max(lo, x + 1); }   // "<="
    }
    if (lo <= hi) cout << lo << "\n";
    else cout << "Impossible\n";
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    long long a, b, c, d; cin >> a >> b >> c >> d;
    long long num, den;
    if (c * b >= a * d) { num = c * b - a * d; den = c * b; }   // movie fills the width
    else                { num = a * d - b * c; den = a * d; }   // movie fills the height
    long long g = std::gcd(num, den);   // gcd(0, den) = den gives "0/1"
    cout << num / g << "/" << den / g << "\n";
}

