#include <bits/stdc++.h>
using namespace std;
int main() {
    int r, c; cin >> r >> c;
    if (r == 1 && c == 1) { cout << 0 << "\n"; return 0; }
    for (int i = 1; i <= r; i++) {
        for (int j = 1; j <= c; j++) {
            long long v;
            if (c == 1) v = i + 1;          // row gcds 2..r+1, column gcd 1
            else v = (long long)i * (r + j); // row gcds 1..r, column gcds r+1..r+c
            cout << v << (j == c ? '\n' : ' ');
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, k; cin >> n >> k;
    vector<long long> s(n);
    for (auto &x : s) cin >> x;
    if (n <= k) { cout << s[n - 1] << "\n"; return 0; }   // one cowbell per box
    int singles = 2 * k - n;      // the largest cowbells go alone
    int m = 2 * (n - k);          // the smallest m cowbells are paired up
    long long ans = singles > 0 ? s[n - 1] : 0;
    for (int i = 0; i < m / 2; i++) ans = max(ans, s[i] + s[m - 1 - i]);  // smallest with largest
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; string s; cin >> n >> s;
    int A = 0, B = 0, C = 0, D = 0;
    for (int i = 0; i < n; i++) {
        if (i % 2 == 0) { if (s[i] == 'b') A++; else C++; }   // even index: wanted 'r' pattern
        else            { if (s[i] == 'r') B++; else D++; }   // odd index
    }
    // pattern "rbrb..": A blacks and B reds are wrong; a swap fixes one of each, a repaint one
    // pattern "brbr..": C reds and D blacks are wrong
    int ans = min(max(A, B), max(C, D));
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    map<int, long long> L, R;   // L[x]: can be the left part with balance x
                                // R[x]: can be the right part whose balance is -x
    for (int i = 0; i < n; i++) {
        string s; cin >> s;
        int bal = 0, mn = 0;
        for (char ch : s) { bal += (ch == '(') ? 1 : -1; mn = min(mn, bal); }
        if (bal >= 0 && mn >= 0) L[bal]++;
        if (bal <= 0 && mn >= bal) R[-bal]++;
    }
    long long ans = L[0] / 2;   // balanced strings pair among themselves
    for (auto &[x, cl] : L) {
        if (x == 0) continue;
        auto it = R.find(x);
        if (it != R.end()) ans += min(cl, it->second);
    }
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    const long long M = 500000;
    printf("%d\n", n + 1);
    printf("1 %d %lld\n", n, M);              // lift everything so each a_i > 2*(i-1)
    for (int i = 1; i <= n; i++) {
        long long cur = a[i - 1] + M;         // untouched by earlier ops (they only use prefixes < i)
        long long t = i - 1;                  // target value: 0,1,...,n-1
        printf("2 %d %lld\n", i, cur - t);    // cur mod (cur-t) = t, earlier targets stay below modulus
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, k; cin >> n >> k;
    vector<int> a(n);
    for (auto &x : a) cin >> x;
    vector<pair<int, int>> ops;
    while ((int)ops.size() < k) {
        int hi = max_element(a.begin(), a.end()) - a.begin();
        int lo = min_element(a.begin(), a.end()) - a.begin();
        if (a[hi] - a[lo] <= 1) break;     // cannot improve further
        a[hi]--; a[lo]++;
        ops.push_back({hi + 1, lo + 1});
    }
    int mx = *max_element(a.begin(), a.end());
    int mn = *min_element(a.begin(), a.end());
    printf("%d %d\n", mx - mn, (int)ops.size());
    for (auto [i, j] : ops) printf("%d %d\n", i, j);
}
